// MongoDB Shell 操作示例

// 插入一条
db.users.insertOne({
  name: '张三',
  email: 'zhang@example.com',
  age: 25,
  hobbies: ['编程', '游戏'],
  address: { city: '北京', district: '海淀' }
});

// 批量插入
db.users.insertMany([
  { name: '李四', age: 30 },
  { name: '王五', age: 28 }
]);

// 查询所有
db.users.find();

// 条件查询
db.users.find({ age: { $gte: 25 } });
db.users.find({ hobbies: '编程' });

// 更新
db.users.updateOne(
  { name: '张三' },
  { $set: { age: 26 }, $push: { hobbies: '阅读' } }
);

// 删除
db.users.deleteOne({ name: '李四' });

const mongoose = require('mongoose');

mongoose.connect('mongodb://localhost:27017/demo');

const userSchema = new mongoose.Schema({
  name: { type: String, required: [true, '名字必填'] },
  email: { type: String, unique: true, lowercase: true },
  age: { type: Number, min: 0, max: 150 },
  role: { type: String, enum: ['user', 'admin'], default: 'user' }
}, { timestamps: true });

const User = mongoose.model('User', userSchema);

async function demo() {
  // 清空测试数据
  await User.deleteMany({});

  // 创建
  const user = await User.create({
    name: '张三', email: 'zhang@test.com', age: 25
  });
  console.log('创建:', user.name, user._id);

  // 查询
  const all = await User.find().sort({ createdAt: -1 });
  console.log('共', all.length, '个用户');

  // 更新
  await User.findByIdAndUpdate(user._id, { age: 26 });
  console.log('已更新');

  // 验证
  try {
    await User.create({ name: '' }); // 会触发 required 验证
  } catch (e) {
    console.log('验证失败:', e.message);
  }

  mongoose.disconnect();
}

demo().catch(console.error);
